# Experiment 3F: compare subject distributions with box plots.
source("r/common.R"); library(ggplot2); library(tidyr); d<-load_students(); long<-pivot_longer(d,cols=all_of(subjects),names_to="Subject",values_to="Score"); p<-ggplot(long,aes(Subject,Score,fill=Subject))+geom_boxplot(alpha=.75,outlier.colour="#B84A4A")+geom_jitter(width=.12,alpha=.45,size=1.8)+scale_fill_brewer(palette="Set2")+labs(title="Score Distribution by Subject",x="Subject",y="Score")+theme_light()+theme(legend.position="none"); ggsave(save_plot_path("3F_subject_boxplots.png"),p,width=8,height=5,dpi=180); print(p)
